def copiar_meta_mensal_para_cada_mes(apps, schema_editor):
    """A meta mensal única do ano vira uma meta igual em cada um dos 12 meses."""
    MetaEconomia = apps.get_model('transacoes', 'MetaEconomia')
    MetaMensal = apps.get_model('transacoes', 'MetaMensal')
    for meta in MetaEconomia.objects.exclude(valor__isnull=True):
        for mes in range(1, 13):
            MetaMensal.objects.get_or_create(
                ano=meta.ano, mes=mes, defaults={'tipo': meta.tipo, 'valor': meta.valor}
            )


def voltar_meta_unica(apps, schema_editor):
    MetaEconomia = apps.get_model('transacoes', 'MetaEconomia')
    MetaMensal = apps.get_model('transacoes', 'MetaMensal')
    for mensal in MetaMensal.objects.filter(mes=1):
        MetaEconomia.objects.update_or_create(
            ano=mensal.ano, defaults={'tipo': mensal.tipo, 'valor': mensal.valor}
        )


